test('Harmonies all32 solid animal models have distinct species and visible volume',async({page})=>{
 const {animalModel,animalDiagramModel,SPECIES}=await import('../../src/client/harmonies-animals.js');
 const {ANIMALS}=await import('../../src/games/harmonies/data.js');
 const {readFile}=await import('node:fs/promises');
 await page.goto('/games/harmonies');await page.setViewportSize({width:1280,height:1000});
 const css=await readFile('src/client/harmonies.css','utf8');
 await page.setContent(`<style>${css}.models{display:grid;grid-template-columns:repeat(8,1fr);gap:12px;padding:12px;background:#f4e6bb}.specimen{background:#fff4d2;text-align:center;color:#234b4d;padding:8px;border:1px solid #b8a36c}.stage{position:relative;height:150px;perspective:500px}.plane{position:absolute;inset:0 50% 0 0;transform-style:preserve-3d;transform:rotateX(32deg) rotateZ(-5deg)}.ground{position:absolute;left:calc(50% - 26px);top:calc(50% - 26px);width:52px;height:52px;border-radius:50%;background:#b8cd83;box-shadow:0 4px #849953}.specimen> .stage>svg{position:absolute;right:0;top:35px;width:70px;height:80px}.specimen p{font-size:14px;margin:0}</style><main class="models">${ANIMALS.map(c=>`<section class="specimen"><div class="stage"><div class="plane"><div class="ground"></div>${animalModel(c.id,0)}</div><svg viewBox="-38 -38 76 76" aria-label="โมเดลบนการ์ด">${animalDiagramModel(c.id)}</svg></div><p>${c.name}</p></section>`).join('')}</main>`);
 expect(Object.keys(SPECIES).sort()).toEqual(ANIMALS.map(c=>c.animal).sort());
 await expect(page.locator('.hm-animal-model')).toHaveCount(32);await expect(page.locator('.hm-pattern-animal')).toHaveCount(32);for(const model of await page.locator('.hm-pattern-animal').all()){expect(await model.locator('polygon').count()).toBeGreaterThan(10);expect(await model.innerHTML()).not.toMatch(/NaN|Infinity/);}
 for(const model of await page.locator('.hm-animal-model').all()){expect(await model.locator('.hm-animal-face').count()).toBeGreaterThan(30);expect(await model.evaluate(el=>getComputedStyle(el).transformStyle)).toBe('preserve-3d');}
 await page.screenshot({path:'data/qa-harmonies-reference/harmonies-all-animal-models.png',fullPage:true});
});

test('Harmonies reference all32 full-art cards retain exact habitat stacks, cubes, scores and real generated files',async({page,baseURL})=>{
 const {cardFace}=await import('../../src/client/harmonies-presentation.js'),{ANIMALS}=await import('../../src/games/harmonies/data.js'),{readFile,mkdir}=await import('node:fs/promises');
 await mkdir('data/qa-harmonies-reference',{recursive:true});await page.goto('/games/harmonies');const css=await readFile('src/client/harmonies.css','utf8');
 await page.setContent(`<base href="${baseURL}"><style>${css}.audit{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:12px;padding:14px;background:#07534b}.audit .hm-inspect{display:block;width:100%}.audit .hm-animal{width:100%}</style><main class="hm-root audit">${ANIMALS.map(c=>`<article class="hm-animal" data-card="${c.id}"><button class="hm-inspect" aria-label="${c.name}">${cardFace(c.id)}</button></article>`).join('')}</main>`);await page.setViewportSize({width:1600,height:1000});
 for(const c of ANIMALS){const card=page.locator(`[data-card="${c.id}"]`);await expect(card.locator('.hm-animal-art img')).toHaveAttribute('src',`/art/harmonies/reference/${c.id}-small.webp`);await expect(card.locator('.hm-pattern-stack')).toHaveCount(c.pattern.length);await expect(card.locator('.hm-pattern-cube')).toHaveCount(1);expect(await card.locator('.hm-card-points>span>b').allTextContents()).toEqual(c.points.map(String));for(let i=0;i<c.pattern.length;i++){const p=c.pattern[i],stack=card.locator('.hm-pattern-stack').nth(i);await expect(stack).toHaveAttribute('data-q',String(p.q));await expect(stack).toHaveAttribute('data-r',String(p.r));await expect(stack.locator('.hm-token')).toHaveCount(p.stack[0]==='building'?2:p.stack.length);const height=p.stack[0]==='building'?2:p.stack.length;await expect(stack.locator('.hm-pattern-height')).toHaveCount(height>1?1:0);if(height>1)await expect(stack.locator('.hm-pattern-height')).toHaveText('×'+height);}}
 await page.locator('.hm-animal-art img').evaluateAll(els=>Promise.all(els.map(async el=>{const image=el as HTMLImageElement;image.loading='eager';await image.decode();})));await page.screenshot({path:'data/qa-harmonies-reference/all32-cards.png',fullPage:true});const scoreSizes=await page.locator('.hm-card-points').evaluateAll(rails=>rails.map(rail=>({steps:Number((rail as HTMLElement).style.getPropertyValue('--score-steps')),height:rail.getBoundingClientRect().height})));for(const a of scoreSizes)for(const b of scoreSizes)if(a.steps<b.steps)expect(a.height).toBeLessThan(b.height);const overlap=await page.locator('.hm-animal').evaluateAll(cards=>cards.flatMap(card=>{const score=card.querySelector('.hm-card-points')!.getBoundingClientRect();return [...card.querySelectorAll('.hm-diagram .hm-cap,.hm-diagram .hm-pattern-height')].filter(cap=>{const r=cap.getBoundingClientRect();return r.right>score.left+1&&r.left<score.right-1&&r.bottom>score.top+1&&r.top<score.bottom-1;}).map(()=>card.getAttribute('data-card'));}));expect(overlap).toEqual([]);const labelsFit=await page.locator('.hm-animal').evaluateAll(cards=>cards.every(card=>{const b=card.querySelector('.hm-inspect')!.getBoundingClientRect();return [...card.querySelectorAll('.hm-pattern-height')].every(label=>{const r=label.getBoundingClientRect();return r.left>=b.left&&r.right<=b.right&&r.top>=b.top&&r.bottom<=b.bottom&&parseFloat(getComputedStyle(label.querySelector('b')!).fontSize)>=7;});}));expect(labelsFit).toBeTruthy();await page.setViewportSize({width:320,height:568});const narrowStyle=await page.addStyleTag({content:'.audit{grid-template-columns:repeat(4,59.75px);width:300px;gap:6px;padding:0}'});const narrowFit=await page.locator('.hm-animal').evaluateAll(cards=>cards.flatMap(card=>{const b=card.querySelector('.hm-inspect')!.getBoundingClientRect(),score=card.querySelector('.hm-card-points')!.getBoundingClientRect();return [...card.querySelectorAll('.hm-pattern-height')].filter(label=>{const r=label.getBoundingClientRect();return r.left<b.left||r.right>b.right||r.top<b.top||r.bottom>b.bottom||(r.right>score.left+1&&r.left<score.right-1&&r.bottom>score.top+1&&r.top<score.bottom-1);}).map(()=>card.getAttribute('data-card'));}));expect(narrowFit).toEqual([]);await narrowStyle.evaluate(el=>el.parentNode?.removeChild(el));await page.setViewportSize({width:1600,height:1000});const m=JSON.parse(await readFile('docs/games/harmonies/reference-redesign/asset-manifest.json','utf8'));expect(m.assets).toHaveLength(37);for(const a of m.assets){const r=await page.request.get(a.file);expect(r.ok(),a.id).toBeTruthy();expect(r.headers()['content-type']).toContain('webp');}
 await page.setContent(`<base href="${baseURL}"><style>${css}.hm-dialog.audit-pair{position:static;display:flex;gap:20px;width:780px;max-width:none;max-height:none;padding:20px;margin:0;background:#07534b}.audit-pair .hm-large-card{width:360px;flex:none}</style><section class="hm-dialog audit-pair">${['animal-07','animal-20'].map(id=>`<div class="hm-large-card">${cardFace(id,0,true)}</div>`).join('')}</section>`);await page.locator('img').evaluateAll(images=>Promise.all(images.map(img=>(img as HTMLImageElement).decode())));await page.evaluate(()=>document.fonts.ready);await expect(page.locator('.audit-pair .hm-pattern-cube')).toHaveCount(0);await expect(page.locator('.audit-pair .hm-pattern-figurine img')).toHaveCount(2);const examplesFit=await page.locator('.audit-pair .hm-large-card').evaluateAll(cards=>cards.every(card=>{const bounds=card.getBoundingClientRect();return [...card.querySelectorAll('.hm-pattern-base,.hm-cap,.hm-pattern-figurine img,.hm-pattern-height')].every(token=>{const r=token.getBoundingClientRect();return r.left>=bounds.left-1&&r.right<=bounds.right+1&&r.top>=bounds.top&&r.bottom<=bounds.bottom+1;});}));expect(examplesFit).toBeTruthy();await expect(page.locator('.audit-pair .hm-pattern-height')).not.toHaveCount(0);expect(await page.locator('.audit-pair .hm-card-points>span>b').evaluateAll(xs=>xs.every(el=>el.scrollWidth<=el.clientWidth))).toBeTruthy();await page.locator('.audit-pair').screenshot({path:'data/qa-harmonies-reference/harmonies-score-reference-pair.png'});
});

test('Harmonies shared display: manager opt-in, landscape overview and alternating host/phone actions',async({browser})=>{
 const contexts:BrowserContext[]=[];
 const make=async(mobile=false)=>{const c=await browser.newContext({viewport:mobile?{width:390,height:844}:{width:1440,height:1000},isMobile:mobile,hasTouch:mobile});contexts.push(c);const p=await c.newPage();await capture(p);p.setDefaultTimeout(12000);return p;};
 try{
  const host=await make();await host.goto('/games/harmonies');await testAccount(host);await host.getByRole('button',{name:'สร้างห้องบนจอกลาง'}).click();const code=await host.locator('.room-code strong').innerText(),phones:Page[]=[];
  for(let i=0;i<2;i++){const p=await make(true);phones.push(p);await p.goto('/play/'+code);await p.getByRole('textbox',{name:'ชื่อของคุณ'}).fill('สวน '+(i+1));await p.getByRole('button',{name:'เข้าห้อง',exact:true}).click();await p.getByRole('button',{name:'พร้อมเล่น',exact:true}).click();}
  const ids=await Promise.all(phones.map(async p=>(await read(p)).me!.id));await host.locator('#starter').selectOption(ids[0]);await host.getByRole('button',{name:'เริ่มเกม',exact:true}).click();await expect(host.locator('.hm-player')).toHaveCount(2);
  const viewer=await make();await viewer.goto('/display/'+code);await expect(viewer.locator('.hm-player')).toHaveCount(2);await expect(viewer.locator('.hm-groups button').first()).toBeDisabled();expect((await read(viewer)).displayControl).toBeUndefined();
  const boxes=await host.locator('.hm-player').evaluateAll(els=>els.map(el=>{const r=el.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width};}));expect(boxes[1].x).toBeGreaterThan(boxes[0].x+boxes[0].width-1);expect(boxes[0].y).toBeCloseTo(boxes[1].y,1);
  for(const empty of await host.locator('.hm-owned-empty').all())await expect(empty).toBeVisible();await expect(host.locator('.hm-market-slot')).toHaveCount(5);
  await host.locator('.hm-view-options>summary').click();await host.locator('#hm-display-mode').selectOption('shared-table');await expect(host.locator('.hm-root')).toHaveClass(/hm-display-interactive/);await host.locator('.hm-view-options>summary').click();expect((await read(host)).me).toBeUndefined();expect((await read(host)).displayControl!.id).toBe(ids[0]);
  await phones[1].locator('.hm-view-options>summary').click();await phones[1].locator(`[data-tab="${ids[0]}"]`).click();await phones[1].mouse.click(4,400);
  let v=await read(host);const group=v.displayControl!.legal.find(a=>a.type==='harmonies-group')!;await host.locator(`[data-group="${group.group}"]`).click();await confirmPickup(host);await Promise.all([host,...phones,viewer].map(p=>revision(p,v.revision+1)));
  const place=async(surface:Page)=>{const before=await read(surface),control=before.me??before.displayControl!,action=control.legal.find(a=>a.type==='harmonies-place')!;await surface.locator(`[data-token="${action.token}"]`).click();await surface.locator(`.hm-player[data-player="${control.id}"] [data-cell="${action.cell}"]`).click();await expect(surface.locator('#hm-confirm')).toBeEnabled();await surface.locator('#hm-confirm').click();await Promise.all([host,...phones,viewer].map(p=>revision(p,before.revision+1)));};
  await expect(phones[1].locator('.chosen-board .hm-observed-token')).toHaveCount(3);await expect(phones[1].locator('.chosen-board [data-token],.chosen-board #hm-end')).toHaveCount(0);await phones[1].screenshot({path:'data/qa-harmonies-reference/harmonies-observing-friend.png'});
  await place(host);await expect(phones[1].locator('.chosen-board .hm-observed-token')).toHaveCount(2);await place(phones[0]);await place(host);
  v=await read(host);const claim=v.displayControl!.legal.find(a=>a.type==='harmonies-card')!;await host.locator(`[data-claim="${claim.card}"]`).click();await confirmPickup(host);await revision(host,v.revision+1);await expect(host.locator(`[data-ui-key="owned-${claim.card}"] .hm-inspect`)).toBeVisible();
  v=await read(host);await host.locator('#hm-end').click();await revision(host,v.revision+1);expect((await read(host)).displayControl!.id).toBe(ids[1]);await revision(phones[1],v.revision+1);await expect(phones[1].locator('.hm-turn-dialog')).toBeVisible();await phones[1].screenshot({path:'data/qa-harmonies-reference/harmonies-your-turn.png'});await phones[1].locator('#hm-return-home').click();await expect(phones[1].locator('.chosen-board')).toHaveAttribute('data-player',ids[1]);await expect(phones[1].locator('.hm-turn-dialog')).toHaveCount(0);
  v=await read(phones[1]);const next=v.me!.legal.find(a=>a.type==='harmonies-group')!;await phones[1].locator(`[data-group="${next.group}"]`).click();await host.locator(`[data-group="${next.group}"]`).click();await confirmPickup(host);await revision(phones[1],v.revision+1);await expect(phones[1].locator('.hm-choice-dialog')).toHaveCount(0);await revision(host,v.revision+1);await place(host);
  await host.reload();await expect(host.locator('.hm-root')).toHaveClass(/hm-display-interactive/);expect((await read(host)).displayControl!.id).toBe(ids[1]);await expect(viewer.locator('[data-token],#hm-confirm,[data-available-animal]')).toHaveCount(0);expect((await read(viewer)).displayControl).toBeUndefined();
  await host.screenshot({path:'data/qa-harmonies-reference/harmonies-shared-display-interactive.png',fullPage:true});await viewer.screenshot({path:'data/qa-harmonies-reference/harmonies-shared-display-readonly.png',fullPage:true});
  await host.setViewportSize({width:1024,height:768});await host.screenshot({path:'data/qa-harmonies-reference/harmonies-shared-display-landscape-ipad.png',fullPage:true});expect(await host.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(1024);
  v=await read(host);await host.locator('.hm-view-options>summary').click();await host.locator('#hm-display-mode').selectOption('full-mobile');await revision(host,v.revision+1);await host.locator('.hm-view-options>summary').click();expect((await read(host)).displayControl).toBeUndefined();await expect(host.locator('[data-token],#hm-end')).toHaveCount(0);await expect(phones[1].locator('[data-token]')).toHaveCount(2);
 }finally{for(const c of contexts)await c.close();}
});
